const af = 0.02;
const maxAf = 0.2;
const PERIOD_MS = 5 * 60 * 1000; // 5分钟K线周期
const MAX_SIGNAL = 100;
const RSI_PERIOD = 14;
const BOLL_PERIOD = 20;  // 布林带周期
const BOLL_K = 2;

// 币种名称
const SYMBOL = 'LINK';

function formatTime(ms) {
    const date = new Date(parseInt(ms) + PERIOD_MS);
    return date.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });
}

// 计算 RSI
function calculateRSI(closes, period=RSI_PERIOD) {
    let rsiArray = [];
    let gains = [], losses = [];

    for (let i = 1; i <= period; i++) {
        const diff = closes[i] - closes[i-1];
        gains.push(diff > 0 ? diff : 0);
        losses.push(diff < 0 ? -diff : 0);
    }

    let avgGain = gains.reduce((a,b)=>a+b,0)/period;
    let avgLoss = losses.reduce((a,b)=>a+b,0);

    rsiArray[period] = 100 - (100 / (1 + avgGain/avgLoss));

    for (let i = period+1; i < closes.length; i++) {
        const diff = closes[i] - closes[i-1];
        const gain = diff > 0 ? diff : 0;
        const loss = diff < 0 ? -diff : 0;
        avgGain = (avgGain*(period-1) + gain)/period;
        avgLoss = (avgLoss*(period-1) + loss)/period;
        rsiArray[i] = 100 - (100 / (1 + avgGain/avgLoss));
    }

    for (let i = 0; i < period; i++) rsiArray[i] = null;

    return rsiArray;
}

// 计算布林带
function calculateBollingerBands(closes, period=BOLL_PERIOD, k=BOLL_K) {
    let bands = [];
    for (let i = 0; i < closes.length; i++) {
        if (i < period - 1) {
            bands.push({ MB: null, UB: null, LB: null });
            continue;
        }

        const window = closes.slice(i - period + 1, i + 1);
        const sum = window.reduce((a,b) => a+b, 0);
        const MB = sum / period;
        const variance = window.reduce((a,b) => a + Math.pow(b-MB,2), 0) / period;
        const stdDev = Math.sqrt(variance);

        bands.push({
            MB: MB,
            UB: MB + k*stdDev,
            LB: MB - k*stdDev
        });
    }
    return bands;
}

// 计算 SAR + RSI + Boll MB-SAR
function calculateSARRSIBollMB(data) {
    let result = [];

    let uptrend = true;
    let sar = parseFloat(data[0][3]);
    let afCurr = af;
    let ep = parseFloat(data[0][2]);
    let currentTrend = null;
    let trendCount = 0;

    const closes = data.map(d => parseFloat(d[4]));
    const rsiValues = calculateRSI(closes, RSI_PERIOD);
    const bb = calculateBollingerBands(closes, BOLL_PERIOD, BOLL_K);

    for (let i = 1; i < data.length; i++) {
        const open = parseFloat(data[i][1]);
        const high = parseFloat(data[i][2]);
        const low = parseFloat(data[i][3]);
        const close = parseFloat(data[i][4]);

        let newTrend = currentTrend;

        if (uptrend) {
            sar = sar + afCurr * (ep - sar);
            if (low < sar) {
                uptrend = false;
                sar = ep;
                ep = low;
                afCurr = af;
                newTrend = '空头';
                trendCount = 0;
            } else {
                if (high > ep) ep = high;
                afCurr = Math.min(afCurr + af, maxAf);
                if (currentTrend !== '多头') trendCount = 0;
                newTrend = '多头';
            }
        } else {
            sar = sar + afCurr * (ep - sar);
            if (high > sar) {
                uptrend = true;
                sar = ep;
                ep = high;
                afCurr = af;
                newTrend = '多头';
                trendCount = 0;
            } else {
                if (low < ep) ep = low;
                afCurr = Math.min(afCurr + af, maxAf);
                if (currentTrend !== '空头') trendCount = 0;
                newTrend = '空头';
            }
        }

        if (currentTrend === newTrend) trendCount = (trendCount + 1) % (MAX_SIGNAL + 1);
        currentTrend = newTrend;

        // SAR 差值
        let sarDiff = null;
        if (currentTrend === '多头') sarDiff = low - sar;
        else if (currentTrend === '空头') sarDiff = sar - high;

        // 涨跌幅
        const change = ((close - open)/open*100).toFixed(2) + '%';

        // Boll MB - SAR
        let bollSarDiff = null;
        const bbItem = bb[i] || { MB: null };
        if (bbItem.MB !== null) {
            bollSarDiff = bbItem.MB - sar;
        }

        result.push({
            symbol: SYMBOL,
            index: i,
            time: formatTime(data[i][0]),
            timestamp: data[i][0],
            open: open,
            high: high,
            low: low,
            close: close,
            volume: data[i][5],
            sar: sar,
            signal: `${currentTrend}${trendCount.toString().padStart(2,'0')}`,
            rsi_5min: rsiValues[i] !== null ? parseFloat(rsiValues[i].toFixed(2)) : null,
            sar差值: sarDiff !== null ? parseFloat(sarDiff.toFixed(4)) : null,
            change: change,
            boll_sar_diff: bollSarDiff !== null ? parseFloat(bollSarDiff.toFixed(4)) : null
        });
    }

    return result;
}

