                trendCount = 0;
            } else {
                if (high > ep) ep = high;
                afCurr = Math.min(afCurr + af, maxAf);
                if (currentTrend !== '多头') trendCount = 0;
                newTrend = '多头';
            }
        } else {
            sar = sar + afCurr * (ep - sar);
            if (high > sar) {
                uptrend = true;
                sar = ep;
                ep = high;
                afCurr = af;
                newTrend = '多头';
                trendCount = 0;
            } else {
                if (low < ep) ep = low;
                afCurr = Math.min(afCurr + af, maxAf);
                if (currentTrend !== '空头') trendCount = 0;
                newTrend = '空头';
            }
        }

        if (currentTrend === newTrend) trendCount = (trendCount + 1) % (MAX_SIGNAL + 1);
        currentTrend = newTrend;

        let sarDiff = currentTrend === '多头' ? low - sar : sar - high;

// === 涨跌幅（数值） ===
const change = parseFloat(((close - open) / open * 100).toFixed(2));

// === 波动百分比（数值） ===
const 波动百分比 = parseFloat(((high - low) / open * 100).toFixed(2));

const bbItem = bb[i] || { MB: null };
const bollSarDiff = bbItem.MB !== null ? bbItem.MB - sar : null;


        // === 新高 / 新低 检测 ===
        let highFlag = 0, lowFlag = 0;
        if (i >= HIGH_LOW_LOOKBACK) {
            const prevHighs = highs.slice(i - HIGH_LOW_LOOKBACK, i);
            const prevLows = lows.slice(i - HIGH_LOW_LOOKBACK, i);
            if (high > Math.max(...prevHighs)) highFlag = 1;
            if (low < Math.min(...prevLows)) lowFlag = 1;
        }

        result.push({
    symbol: SYMBOL,
    idx: i,
    time: formatTime(data[i][0]),
    timestamp: data[i][0],
    波动百分比,   // ✅ 已经是数值
    open, high, low, close,
    volume: data[i][5],
    sar,
    signal: `${currentTrend}${trendCount.toString().padStart(2, '0')}`,
    rsi_5min: rsiValues5m[i] !== null ? parseFloat(rsiValues5m[i].toFixed(2)) : null,
    rsi_1h: rsiValues1h[i] !== null ? parseFloat(rsiValues1h[i].toFixed(2)) : null,
    sar差值: sarDiff !== null ? parseFloat(sarDiff.toFixed(4)) : null,
    change,  // ✅ 已经是数值
    boll_sar_diff: bollSarDiff !== null ? parseFloat(bollSarDiff.toFixed(4)) : null,
    新高: highFlag,
    新低: lowFlag
});

    }

    return result;
}

return calculateSARRSIBollMB(rawData).map(x => ({ json: x }));

